void unregister_memcg_threshold(struct cgroup *cgrp, struct cftype *cft, struct eventfd_ctx *eventfd)
{
    struct mem_cgroup *memcg = cgroup_to_memcg(cgrp);
    struct memcg_threshold *thresholds, *new_thresholds;
    int type, idx, new_size;
    int i = 0, j = 0;

    mutex_lock(&memcg->thresholds_lock);

    type = cft->private;
    thresholds = memcg->thresholds[type];
    new_size = memcg->thresholds_count[type] - 1;

    if (new_size <= 0) {
        mutex_unlock(&memcg->thresholds_lock);
        return;
    }

    new_thresholds = kmalloc(new_size * sizeof(struct memcg_threshold), GFP_KERNEL);
    if (!new_thresholds) {
        mutex_unlock(&memcg->thresholds_lock);
        return;
    }

    for (i = 0; i < memcg->thresholds_count[type]; i++) {
        if (thresholds[i].eventfd != eventfd) {
            new_thresholds[j++] = thresholds[i];
        }
    }

    memcg->thresholds[type] = new_thresholds;
    memcg->thresholds_count[type] = new_size;

    mutex_unlock(&memcg->thresholds_lock);
}

void unregister_memcg_event_threshold(struct cgroup *cgrp, struct cftype *cft, struct eventfd_ctx *eventfd)
{
    struct mem_cgroup *memcg = cgroup_to_mem_cgroup(cgrp);
    struct memcg_event_control *thresholds;
    size_t new_size;
    int i, j;

    mutex_lock(&memcg->thresholds_lock);

    if (memcg->current_threshold_array_in_use) {
        thresholds = memcg->primary_thresholds;
    } else {
        thresholds = memcg->spare_thresholds;
    }

    new_size = 0;
    for (i = 0; i < thresholds->count; i++) {
        if (thresholds->entries[i].eventfd != eventfd) {
            thresholds->entries[new_size++] = thresholds->entries[i];
        }
    }

    thresholds->count = new_size;
    thresholds->current_index = (thresholds->current_index + 1) % thresholds->size;

    if (memcg->current_threshold_array_in_use) {
        memcg->primary_thresholds = memcg->spare_thresholds;
        memcg->spare_thresholds = thresholds;
    }

    mutex_unlock(&memcg->thresholds_lock);
}

void unregister_memcg_event_threshold(struct cgroup *cgrp, struct cftype *cft, struct eventfd_ctx *eventfd)
{
    struct mem_cgroup *memcg = cgroup_to_memcg(cgrp);
    int type = cft->private;
    struct threshold *thresholds = memcg->thresholds[type].thresholds;
    struct threshold *new_thresholds;
    int i, j, count = 0;

    mutex_lock(&memcg->thresholds[type].lock);

    for (i = 0; i < memcg->thresholds[type].count; i++) {
        if (thresholds[i].eventfd != eventfd)
            count++;
    }

    new_thresholds = kmalloc_array(count, sizeof(struct threshold), GFP_KERNEL);
    if (!new_thresholds) {
        mutex_unlock(&memcg->thresholds[type].lock);
        return;
    }

    for (i = 0, j = 0; i < memcg->thresholds[type].count; i++) {
        if (thresholds[i].eventfd != eventfd) {
            new_thresholds[j++] = thresholds[i];
        }
    }

    memcg->thresholds[type].thresholds = new_thresholds;
    memcg->thresholds[type].count = count;

    mutex_unlock(&memcg->thresholds[type].lock);
}

void unregister_memcg_oom_event(struct cgroup *cgrp, struct cftype *cft, struct eventfd_ctx *eventfd)
{
    struct mem_cgroup *memcg = cgroup_to_mem_cgroup(cgrp);
    struct memcg_eventfd_list *list;
    struct memcg_eventfd_item *item, *tmp;
    struct cgroup_subsys_state *css = &memcg->css;
    struct cgroup_subsys *ss = css->ss;
    int idx;

    mutex_lock(&memcg->thresholds_lock);

    for (idx = 0; idx < MEMCG_EVENT_TYPES; ++idx) {
        list_for_each_entry_safe(item, tmp, &memcg->eventfds[idx], list) {
            if (item->eventfd == eventfd) {
                list_del(&item->list);
                kfree(item);
            }
        }
    }

    mutex_unlock(&memcg->thresholds_lock);
}

void unregister_memcg_event_threshold(struct cgroup *cgrp, struct cftype *cft,
                                      struct eventfd_ctx *eventfd)
{
    struct mem_cgroup *memcg = mem_cgroup_from_cont(cgrp);
    struct memcg_event_threshold *thresholds, *new_thresholds;
    struct memcg_event_threshold *spare_thresholds;
    int new_size;
    int i, j;

    mutex_lock(&memcg->thresholds_lock);

    if (cft->type == _MEMCG_THRESHOLD_TYPE_A) {
        thresholds = memcg->thresholds_a;
        spare_thresholds = memcg->thresholds_b;
    } else {
        thresholds = memcg->thresholds_b;
        spare_thresholds = memcg->thresholds_a;
    }

    new_size = 0;
    for (i = 0; i < thresholds->size; i++) {
        if (thresholds->events[i].eventfd != eventfd)
            new_size++;
    }

    new_thresholds = kzalloc(sizeof(*new_thresholds) + new_size * sizeof(struct eventfd_entry), GFP_KERNEL);
    if (!new_thresholds) {
        mutex_unlock(&memcg->thresholds_lock);
        return;
    }

    j = 0;
    for (i = 0; i < thresholds->size; i++) {
        if (thresholds->events[i].eventfd != eventfd) {
            new_thresholds->events[j++] = thresholds->events[i];
        }
    }

    new_thresholds->size = new_size;
    if (cft->type == _MEMCG_THRESHOLD_TYPE_A) {
        memcg->thresholds_a = new_thresholds;
    } else {
        memcg->thresholds_b = new_thresholds;
    }

    mutex_unlock(&memcg->thresholds_lock);

    kfree(thresholds);
}
